#pragma once

#include "CoreMinimal.h"
#include "EpicodeCommand.h"

/**
 * Validates and applies JSON edit scripts generated by the assistant. The
 * service is intentionally command-layer code: scripts can only call the same
 * whitelisted commands as the UI and control API.
 */
class EPICODEASSISTANT_API FEpicodeScriptService
{
public:
	static void Register(FEpicodeCommandRegistry& Registry);

	/** Extracts the first JSON object from plain text or a fenced code block. */
	static FString ExtractJsonObject(const FString& Text);

	static const TArray<FString>& GetAllowedMethods();

	struct FValidation
	{
		bool bValid = false;
		bool bRequiresConfirmation = false;
		int32 OperationCount = 0;
		int32 AffectedCount = 0;
		TSharedPtr<FJsonObject> NormalizedScript;
		TArray<FString> Warnings;
		TArray<TSharedPtr<FJsonValue>> Errors;
		TArray<TSharedPtr<FJsonValue>> PreviewOperations;

		TSharedPtr<FJsonObject> ToJson() const;
	};

	static bool Validate(
		const TSharedPtr<FJsonObject>& Script,
		FValidation& OutValidation,
		FString& OutError);
};
